INSERT INTO `dashboard_config` (`id`, `config_json`) VALUES
(1, '{\n    \"prefix\": \"+\",\n    \"staffRoleId\": \"1456798564230631567\",\n    \"ticketCategories\": {\n        \"Ticket Plainte\": {\n            \"id\": \"1456748564591149167\",\n            \"viewRole\": [\n                \"1456748563148312694\",\n                \"1456748563148312693\",\n                \"1456748563148312692\",\n                \"1456755931026161769\",\n                \"1456793392800469002\",\n                \"1456797733494067331\"\n            ],\n            \"mentionRole\": [\n                \"1456793392800469002\"\n            ],\n            \"ticketName\": \"Plainte-{number}\",\n            \"emoji\": \"🚨\",\n            \"style\": \"Secondary\",\n            \"customWelcomeTitle\": \"🚨 Ticket Plainte\",\n            \"customWelcomeMessage\": \"Merci de décrire clairement le problème rencontré :\\n\\n* Personne(s) concernée(s)\\n* Situation détaillée\\n* Date \\/ contexte\\n* Preuves si disponibles (screens, messages, etc.)\\n* Preuves avec GoPro sur votre torse ou autre !\\n\\n⛔ Toute plainte abusive ou mensongère pourra entraîner des plaintes contre vous.\\nNotre équipe traitera votre demande dans les plus brefs délais.\",\n            \"requireUserInfo\": true\n        },\n        \"Ticket Direction\": {\n            \"id\": \"1456791076374581384\",\n            \"viewRole\": [\n                \"1456748563148312694\",\n                \"1456748563148312693\",\n                \"1456748563148312692\",\n                \"1456755931026161769\",\n                \"1456793392800469002\",\n                \"1456797733494067331\"\n            ],\n            \"mentionRole\": [\n                \"1456793392800469002\",\n                \"1456797733494067331\"\n            ],\n            \"ticketName\": \"Direction-{number}\",\n            \"style\": \"Secondary\",\n            \"emoji\": \"🧑‍💼\",\n            \"customWelcomeTitle\": \"🧑‍💼 Ticket Direction\",\n            \"customWelcomeMessage\": \"Vous êtes en contact direct avec la direction.\\nMerci d’expliquer votre demande de manière **claire, respectueuse et détaillée**.\\n\\n⚠️ Ce ticket est strictement confidentiel.\\nMerci de patienter, un membre de la direction vous répondra rapidement.\",\n            \"requireUserInfo\": true\n        },\n        \"Ticket Question\": {\n            \"id\": \"1456843980762386554\",\n            \"viewRole\": [\n                \"1456748563148312694\",\n                \"1456748563148312693\",\n                \"1456748563148312692\",\n                \"1456755931026161769\",\n                \"1456793392800469002\",\n                \"1456797733494067331\"\n            ],\n            \"mentionRole\": [\n                \"1456793392800469002\",\n                \"1456797733494067331\"\n            ],\n            \"ticketName\": \"Question-{number}\",\n            \"emoji\": \"❓\",\n            \"style\": \"Secondary\",\n            \"customWelcomeTitle\": \"❓ Ticket Question\",\n            \"customWelcomeMessage\": \"Merci de poser votre question ou votre demande d’information.\\nNotre équipe est là pour vous aider 💬\\n\\n👉 Plus votre message est précis, plus la réponse sera rapide.\",\n            \"requireUserInfo\": true\n        },\n        \"Devenir Graphiste\": {\n            \"id\": \"1457663196889485548\",\n            \"viewRole\": [\n                \"1456748563148312694\",\n                \"1456748563148312693\",\n                \"1456748563148312692\",\n                \"1456755931026161769\",\n                \"1456793392800469002\",\n                \"1456797733494067331\"\n            ],\n            \"mentionRole\": [\n                \"1456796673262223380\"\n            ],\n            \"customWelcomeTitle\": \"🎨 Devenir Graphiste\",\n            \"customWelcomeMessage\": \"Nous sommes ravis que vous souhaitiez rejoindre notre équipe créative ✨🎨 ! Pour que votre candidature soit traitée rapidement et sérieusement ⏱️✅, merci de remplir **toutes les informations demandées** avec soin ✍️. Plus votre présentation est complète, plus nous pourrons évaluer vos talents et vos motivations 💡💪 !\\n\\n**⚠️ Important :**\\n\\n* 🆔 Pour vos **pièces d’identité (Carte d’identité + Permis de conduire)**, veuillez envoyer des photos **claires et sans accessoires** ❌🕶️🎩 (pas de lunettes de soleil, chapeaux, filtres ou retouches).\\n* 🖼️ Envoyez vos créations\\/photos de manière **lisible et organisée**, avec une petite explication de chaque élément 📝📷.\\n\\n```\\n**Prénom & Nom :** \\n**Date de naissance :** \\n**ID unique :** \\n**Numéro de téléphone :** \\n**Numéro de compte bancaire (RIB) :**\\n\\n**Motivations \\/ Présentez-vous :** \\n\\n**Envoyez trois créations :** \\n**Explication de vos créations :** \\n**Outils utilisés :** \\n**Photo Carte d’identité + Permis de Conduire (sans accessoires) :** \\n```\",\n            \"ticketName\": \"Graphisme-{number}\",\n            \"emoji\": \"🎨\",\n            \"style\": \"Secondary\",\n            \"newRow\": true\n        },\n        \"Devenir Photographe\": {\n            \"id\": \"1457663196889485548\",\n            \"viewRole\": [\n                \"1456748563148312694\",\n                \"1456748563148312693\",\n                \"1456748563148312692\",\n                \"1456755931026161769\",\n                \"1456793392800469002\",\n                \"1456797733494067331\"\n            ],\n            \"mentionRole\": [\n                \"1456796673262223380\"\n            ],\n            \"customWelcomeTitle\": \"📸 Devenir Photographe\",\n            \"customWelcomeMessage\": \"Nous sommes ravis que vous souhaitiez rejoindre notre équipe créative ✨📸 ! Pour que votre candidature soit traitée rapidement et sérieusement ⏱️✅, merci de remplir **toutes les informations demandées** avec soin ✍️. Plus votre présentation est complète, plus nous pourrons évaluer vos talents et vos motivations 💡💪 !\\n\\n**⚠️ Important :**\\n\\n* 🆔 Pour vos **pièces d’identité (Carte d’identité + Permis de conduire)**, veuillez envoyer des photos **claires et sans accessoires** ❌🕶️🎩 (pas de lunettes de soleil, chapeaux, filtres ou retouches).\\n* 🖼️ Envoyez vos créations\\/photos de manière **lisible et organisée**, avec une petite explication de chaque élément 📝📷.\\n\\n```\\n**Prénom & Nom :** \\n**Date de naissance :** \\n**ID unique :** \\n**Numéro de téléphone :** \\n**Numéro de compte bancaire (RIB) :**\\n\\n**Motivations \\/ Présentez-vous :** \\n\\n**Envoyez trois créations :** \\n**Explication de vos créations :** \\n**Outils utilisés :** \\n**Photo Carte d’identité + Permis de Conduire (sans accessoires) :** \\n```\",\n            \"ticketName\": \"Photographe-{number}\",\n            \"emoji\": \"📸\",\n            \"style\": \"Secondary\"\n        },\n        \"Devenir Styliste\": {\n            \"id\": \"1457663196889485548\",\n            \"viewRole\": [\n                \"1456748563148312694\",\n                \"1456748563148312693\",\n                \"1456748563148312692\",\n                \"1456755931026161769\",\n                \"1456793392800469002\",\n                \"1456797733494067331\"\n            ],\n            \"mentionRole\": [\n                \"1456796673262223380\"\n            ],\n            \"ticketName\": \"Styliste-{number}\",\n            \"emoji\": \"👗\",\n            \"customWelcomeTitle\": \"👗 Devenir Styliste\",\n            \"customWelcomeMessage\": \"Nous sommes ravis que vous souhaitiez rejoindre notre équipe créative ✨👗 ! Pour que votre candidature soit traitée rapidement et sérieusement ⏱️✅, merci de remplir **toutes les informations demandées** avec soin ✍️. Plus votre présentation est complète, plus nous pourrons évaluer vos talents et vos motivations 💡💪 !\\n\\n**⚠️ Important :**\\n\\n* 🆔 Pour vos **pièces d’identité (Carte d’identité + Permis de conduire)**, veuillez envoyer des photos **claires et sans accessoires** ❌🕶️🎩 (pas de lunettes de soleil, chapeaux, filtres ou retouches).\\n* 🖼️ Envoyez vos créations\\/photos de manière **lisible et organisée**, avec une petite explication de chaque élément 📝📷.\\n\\n```\\n**Prénom & Nom :** \\n**Date de naissance :** \\n**ID unique :** \\n**Numéro de téléphone :** \\n**Numéro de compte bancaire (RIB) :**\\n\\n**Motivations \\/ Présentez-vous :** \\n\\n**Envoyez trois créations :** \\n**Explication de vos créations :** \\n**Outils utilisés :** \\n**Photo Carte d’identité + Permis de Conduire (sans accessoires) :** \\n```\",\n            \"style\": \"Secondary\"\n        },\n        \"Commande Graphisme\": {\n            \"id\": \"1457401771969347635\",\n            \"viewRole\": [\n                \"1456748563148312693\",\n                \"1456748563148312694\",\n                \"1456748563148312692\",\n                \"1456755931026161769\",\n                \"1456797733494067331\",\n                \"1456793392800469002\",\n                \"1456806786400125099\"\n            ],\n            \"mentionRole\": [\n                \"1456806786400125099\"\n            ],\n            \"emoji\": \"🖌️\",\n            \"style\": \"Secondary\",\n            \"customWelcomeTitle\": \"🖌️ Commande – Graphisme\",\n            \"customWelcomeMessage\": \"Merci de détailler votre demande graphique (Donner toute les informations) :\\n\\n* Type de visuel (logo, affiche, réseaux sociaux, etc.)\\n* Style souhaité\\n* Délais\\n* Budget (si possible)\\n\\n🎨 Un graphiste vous prendra en charge rapidement.\",\n            \"ticketName\": \"Commande-{number}\",\n            \"requireUserInfo\": true,\n            \"privateOnClaim\": false,\n            \"claimable\": false,\n            \"removeRoleOnClaim\": [\n                \"1456802489729945813\"\n            ],\n            \"newRow\": true\n        },\n        \"Commande Photographe\": {\n            \"id\": \"1457398943297179688\",\n            \"viewRole\": [\n                \"1456748563148312694\",\n                \"1456748563148312693\",\n                \"1456748563148312692\",\n                \"1456755931026161769\",\n                \"1456793392800469002\",\n                \"1456797733494067331\",\n                \"1456803871971213433\"\n            ],\n            \"mentionRole\": [\n                \"1456803871971213433\"\n            ],\n            \"emoji\": \"📸\",\n            \"style\": \"Secondary\",\n            \"customWelcomeTitle\": \"📸 Commande – Photographe\",\n            \"customWelcomeMessage\": \"Merci de préciser :\\n\\n* Type de shooting (événement, produit, portrait, etc.)\\n* Date et lieu\\n* Style souhaité\\n* Budget estimé\\n* La personne que vous désirez pour prendre vos photos (si vous avez déjà quelqu\'un en tête)\\n\\n📷 Un photographe de notre équipe vous contactera rapidement.\",\n            \"ticketName\": \"Commande-{number}\",\n            \"requireUserInfo\": true,\n            \"claimable\": true,\n            \"privateOnClaim\": true,\n            \"removeRoleOnClaim\": [\n                \"1456803871971213433\"\n            ],\n            \"removeRoleOnClose\": [\n                \"1456803871971213433\"\n            ]\n        },\n        \"Commande Stylisme\": {\n            \"id\": \"1457402258550558720\",\n            \"viewRole\": [\n                \"1456748563148312694\",\n                \"1456748563148312693\",\n                \"1456748563148312692\",\n                \"1456755931026161769\",\n                \"1456793392800469002\",\n                \"1456797733494067331\",\n                \"1456804667467235450\"\n            ],\n            \"mentionRole\": [\n                \"1456804667467235450\"\n            ],\n            \"emoji\": \"👗\",\n            \"style\": \"Secondary\",\n            \"customWelcomeTitle\": \"👗 Commande – Stylisme\",\n            \"customWelcomeMessage\": \"Merci de décrire votre projet de stylisme :\\n\\n* Type de projet\\n* Objectif (shooting, événement, branding, etc.)\\n* Délais\\n* Budget si possible\\n\\n👗 Un styliste vous accompagnera dans votre projet.\",\n            \"ticketName\": \"Commande-{number}\",\n            \"requireUserInfo\": true,\n            \"requireCgu\": true,\n            \"claimable\": true,\n            \"privateOnClaim\": true,\n            \"claimRole\": [\n                \"1456804667467235450\"\n            ],\n            \"removeRoleOnClaim\": [\n                \"1456804667467235450\"\n            ],\n            \"removeRoleOnClose\": [\n                \"1456804667467235450\"\n            ]\n        }\n    },\n    \"ticketSettings\": {\n        \"defaultCategory\": \"support\",\n        \"panelTitle\": \"Nyrex Creative 🎨\",\n        \"panelDescription\": \"# 🎫 **Tickets – Nyrex Creative** 🎨\\nVeuillez utiliser les boutons ci-dessous pour ouvrir un ticket correspondant à votre demande :\\n\\n🚨 **Ticket Plainte**\\n➡️ Pour signaler un problème, un comportement inapproprié ou un litige avec un membre de l’équipe ou un client.\\n\\n🧑‍💼 **Ticket Direction**\\n➡️ Pour contacter la direction de **Nyrex Creative** de manière privée et confidentielle.\\n\\n❓ **Ticket Question**\\n➡️ Pour toute question, information ou demande générale concernant l’agence.\\n\\n🎨 **Devenir Graphiste**\\n➡️ Pour postuler en tant que **Graphiste** au sein de **Nyrex Creative**.\\n\\n📸 **Devenir Photographe**\\n➡️ Pour rejoindre **Nyrex Creative** en tant que **Photographe**.\\n\\n👗 **Devenir Styliste**\\n➡️ Pour intégrer l’équipe **Stylisme** de **Nyrex Creative**.\\n\\n🖌️ **Ticket Commande – Graphisme**\\n➡️ Pour commander nos services de création visuelle\\n(logos, affiches, visuels réseaux sociaux, branding, etc.).\\n\\n📸 **Ticket Commande – Photographe**\\n➡️ Pour réserver nos services de photographie\\n(shootings, événements, portraits, produits…).\\n\\n👗 **Ticket Commande – Stylisme**\\n➡️ Pour bénéficier de nos services de stylisme\\n(conseils, tenues, direction artistique, projets visuels).\",\n        \"buttonLabel\": \"Ouvrir un ticket\",\n        \"ticketWelcomeTitle\": \"🎫 Ticket Support\",\n        \"ticketWelcomeMessage\": \"Bonjour {user}, un membre du staff va prendre en charge votre demande.\",\n        \"viewRole\": \"\",\n        \"mentionRole\": \"\",\n        \"closeCategory\": \"1457471820893782026\",\n        \"maxTickets\": 5,\n        \"globalCategory\": \"\",\n        \"ticketCount\": 263,\n        \"renameRole\": [\n            \"1456796673262223380\",\n            \"1456793392800469002\",\n            \"1456797733494067331\"\n        ],\n        \"employeeRoleId\": \"1456798564230631567\",\n        \"staffRoleId\": \"1456798564230631567\"\n    },\n    \"ticketCategoryOrder\": [],\n    \"employeeRoleId\": \"1456798564230631567\"\n}');
